import{_ as a,o,c as r,a3 as s}from"./chunks/framework.BFeCKmyl.js";const m=JSON.parse('{"title":"Persistir preferências e painéis do processo","description":"","frontmatter":{"title":"Persistir preferências e painéis do processo","id":"eproc-persistir-preferencias-processo","plataforma":"eproc","grupo":"Painel do processo","plano":"free","desde":"1.4.0","padrao":"ligado","head":[["link",{"rel":"canonical","href":"https://eploc.com.br/manual/funcionalidades/eproc-persistir-preferencias-processo"}]]},"headers":[],"relativePath":"funcionalidades/eproc-persistir-preferencias-processo.md","filePath":"funcionalidades/eproc-persistir-preferencias-processo.md"}'),i={name:"funcionalidades/eproc-persistir-preferencias-processo.md"};function c(t,e,p,n,d,l){return o(),r("div",null,e[0]||(e[0]=[s('<h1 id="persistir-preferencias-e-paineis-do-processo" tabindex="-1">Persistir preferências e painéis do processo <a class="header-anchor" href="#persistir-preferencias-e-paineis-do-processo" aria-label="Permalink to &quot;Persistir preferências e painéis do processo&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>Na página do processo, o eproc tem caixas como &quot;Sempre aberto ao iniciar&quot;, &quot;Mostrar preferências da unidade&quot; e &quot;Manter aberto&quot;. Ele mesmo deveria lembrá-las, mas com frequência as reseta sozinho. Este recurso memoriza o que você marcou e corrige o eproc quando ele volta ao padrão.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><p><strong>eproc</strong>, página do processo:</p><ul><li>painéis de Preferências de Minutas, Movimentação, Intimação e Automatizações (caixas &quot;Sempre aberto ao iniciar&quot; e &quot;Mostrar preferências da unidade&quot;);</li><li>caixas &quot;Manter Aberto&quot; de Minutas e de Informações Adicionais.</li></ul><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><ol><li>Marque ou desmarque uma dessas caixas como de costume. Um balão confirma: &quot;O eploc vai lembrar desse ajuste para você&quot;.</li><li>Se o eproc resetar a caixa depois (ao trocar de perfil, recarregar um trecho da página etc.), o eploc a remarca e avisa: &quot;O sistema resetou isso — mas o eploc já corrigiu pra você&quot;.</li><li>Ao abrir um processo, o que deveria começar aberto e está fechado é aberto uma vez.</li></ol><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><p>Não há opções além de ligar e desligar.</p><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><ul><li>Nada é alterado antes de você mexer numa caixa pela primeira vez com o recurso ligado.</li><li>O que você fechar à mão continua fechado até você reabrir ou recarregar a página.</li><li>As escolhas são guardadas separadamente para cada perfil/unidade do eproc.</li></ul>',12)]))}const f=a(i,[["render",c]]);export{m as __pageData,f as default};
